impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        let mut prefix = vec![0; n + 1];
        for i in 0..n {
            prefix[i + 1] = prefix[i] + stone_value[i];
        }

        let mut dp = vec![vec![0; n]; n];

        for len in 2..=n {
            for i in 0..=n - len {
                let j = i + len - 1;
                let mut min_diff = i32::MAX;
                for k in i..j {
                    let left_sum = prefix[k + 1] - prefix[i];
                    let right_sum = prefix[j + 1] - prefix[k + 1];
                    let diff = (left_sum - right_sum).abs();
                    if diff < min_diff {
                        min_diff = diff;
                    }
                    let current = left_sum.min(right_sum) + dp[i][k] + dp[k + 1][j];
                    if current > dp[i][j] {
                        dp[i][j] = current;
                    }
                }
                dp[i][j] += min_diff;
            }
        }

        dp[0][n - 1]
    }
}

